package com.sentinelcore.assetservice.controller; import java.util.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import com.sentinelcore.assetservice.dto.*; import com.sentinelcore.assetservice.service.SecurityReviewService; import jakarta.validation.Valid;
@RestController @RequestMapping("/api/security-reviews") public class SecurityReviewController {private final SecurityReviewService service; public SecurityReviewController(SecurityReviewService s){service=s;} @GetMapping public ResponseEntity<List<SecurityReviewResponse>> all(){return ResponseEntity.ok(service.all());} @PostMapping public ResponseEntity<SecurityReviewResponse> create(@RequestBody SecurityReviewRequest request){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(request));} @PutMapping("/{id}") public ResponseEntity<SecurityReviewResponse> update(@PathVariable UUID id,@RequestBody SecurityReviewRequest request){return ResponseEntity.ok(service.update(id,request));}}